
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_lgap_ge_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_lgap_ge", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([9.456848422314239e+01, 9.090752291249257e+01, 8.590190553308841e+01, 7.920761192468615e+01, 7.053434041735228e+01, 5.979442061073911e+01, 4.732450308391442e+01, 3.410581240604876e+01, 2.177300964142775e+01, 1.208295694627364e+01, 5.669655464970242e+00, 2.566128177623765e+00, 1.915923850647538e+00, 1.278453866882232e+00, 6.637546540111973e-01, 2.916320154769398e-01, 1.602754235469136e-01, 1.882598323920593e-01, 5.184139005316621e-01, 3.615273362008273e+00]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


